@namespace sv_6c71dd576b2f43599dfc557f722459da.Components.Pages.ApplySteps

<nav aria-label="Application steps" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var state = GetStepState(stepIndex);
            <div class="text-center flex-fill">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @GetCircleClass(state)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(state == StepState.Future)"
                        @onclick="() => OnStepClick(stepIndex)">
                    @if (state == StepState.Completed)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </button>
                <div class="small mt-1 @GetLabelClass(state)">@StepNames[stepIndex]</div>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnNavigate { get; set; }

    private static readonly List<string> StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private enum StepState { Completed, Current, Future }

    private StepState GetStepState(int index) =>
        index < CurrentStep ? StepState.Completed :
        index == CurrentStep ? StepState.Current :
        StepState.Future;

    private static string GetCircleClass(StepState state) => state switch
    {
        StepState.Completed => "btn-success text-white",
        StepState.Current => "btn-primary text-white",
        _ => "btn-outline-secondary"
    };

    private static string GetLabelClass(StepState state) => state switch
    {
        StepState.Completed => "text-success fw-semibold",
        StepState.Current => "text-primary fw-semibold",
        _ => "text-muted"
    };

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnNavigate.InvokeAsync(index);
        }
    }
}

@namespace sv_6c71dd576b2f43599dfc557f722459da.Components.Pages.ApplySteps

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
    <input id="fullName" class="form-control @(Errors.ContainsKey("FullName") ? "is-invalid" : "")"
           @bind="Model.FullName" @bind:event="oninput" />
    @if (Errors.TryGetValue("FullName", out var nameErr))
    {
        <div class="invalid-feedback">@nameErr</div>
    }
</div>

<div class="mb-3">
    <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
    <input id="email" type="email"
           class="form-control @(Errors.ContainsKey("Email") ? "is-invalid" : "")"
           @bind="Model.Email" @bind:event="oninput" />
    @if (Errors.TryGetValue("Email", out var emailErr))
    {
        <div class="invalid-feedback">@emailErr</div>
    }
</div>

<div class="mb-3">
    <label for="phone" class="form-label">Phone <span class="text-danger">*</span></label>
    <input id="phone" type="tel" class="form-control @(Errors.ContainsKey("Phone") ? "is-invalid" : "")"
           @bind="Model.Phone" @bind:event="oninput" />
    @if (Errors.TryGetValue("Phone", out var phoneErr))
    {
        <div class="invalid-feedback">@phoneErr</div>
    }
</div>

<div class="mb-3">
    <label for="address" class="form-label">Address <span class="text-danger">*</span></label>
    <textarea id="address" class="form-control @(Errors.ContainsKey("Address") ? "is-invalid" : "")"
              rows="2" @bind="Model.Address" @bind:event="oninput"></textarea>
    @if (Errors.TryGetValue("Address", out var addrErr))
    {
        <div class="invalid-feedback">@addrErr</div>
    }
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="OnNextClick" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next &raquo;</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter] public Dictionary<string, string> Errors { get; set; } = new();
    [Parameter] public bool IsValidating { get; set; }

    private async Task OnNextClick() => await OnNext.InvokeAsync();

    public class PersonalInfoModel
    {
        public string FullName { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
        public string Address { get; set; } = "";
    }
}

@namespace sv_6c71dd576b2f43599dfc557f722459da.Components.Pages.ApplySteps

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                    <input class="form-control @ValidationClass(index, "Company")" @bind="entry.Company" @bind:event="oninput" />
                    @if (GetError(index, "Company") is { } compErr)
                    {
                        <div class="invalid-feedback">@compErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input class="form-control @ValidationClass(index, "Title")" @bind="entry.Title" @bind:event="oninput" />
                    @if (GetError(index, "Title") is { } titleErr)
                    {
                        <div class="invalid-feedback">@titleErr</div>
                    }
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control @ValidationClass(index, "StartDate")" @bind="entry.StartDate" />
                    @if (GetError(index, "StartDate") is { } sdErr)
                    {
                        <div class="invalid-feedback">@sdErr</div>
                    }
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input type="checkbox" class="form-check-input" id="current-@index"
                               @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description <span class="text-danger">*</span></label>
                    <textarea class="form-control @ValidationClass(index, "Description")" rows="3"
                              @bind="entry.Description" @bind:event="oninput"></textarea>
                    @if (GetError(index, "Description") is { } descErr)
                    {
                        <div class="invalid-feedback">@descErr</div>
                    }
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter] public Dictionary<string, string> Errors { get; set; } = new();

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index) => Entries.RemoveAt(index);

    private string? GetError(int index, string field)
    {
        var key = $"Work[{index}].{field}";
        return Errors.TryGetValue(key, out var err) ? err : null;
