{"file_text": "@namespace sv_6c71dd576b2f43599dfc557f722459da.Components.Pages.ApplySteps

<nav aria-label="Application steps" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var state = GetStepState(stepIndex);
            <div class="text-center flex-fill">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @GetCircleClass(state)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(state == StepState.Future)"
                        @onclick="() => OnStepClick(stepIndex)">
                    @if (state == StepState.Completed)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </button>
                <div class="small mt-1 @GetLabelClass(state)">@StepNames[stepIndex]</div>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnNavigate { get; set; }

    private static readonly List<string> StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private enum StepState { Completed, Current, Future }

    private StepState GetStepState(int index) =>
        index < CurrentStep ? StepState.Completed :
        index == CurrentStep ? StepState.Current :
        StepState.Future;

    private static string GetCircleClass(StepState state) => state switch
    {
        StepState.Completed => "btn-success text-white",
        StepState.Current => "btn-primary text-white",
        _ => "btn-outline-secondary"
    };

    private static string GetLabelClass(StepState state) => state switch
    {
        StepState.Completed => "text-success fw-semibold",
        StepState.Current => "text-primary fw-semibold",
        _ => "text-muted"
    };

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnNavigate.InvokeAsync(index);
        }
    }
}
