@namespace sv_6c71dd576b2f43599dfc557f722459da.Components.Pages.ApplySteps

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
    <input id="fullName" class="form-control @(Errors.ContainsKey("FullName") ? "is-invalid" : "")"
           @bind="Model.FullName" @bind:event="oninput" />
    @if (Errors.TryGetValue("FullName", out var nameErr))
    {
        <div class="invalid-feedback">@nameErr</div>
    }
</div>

<div class="mb-3">
    <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
    <input id="email" type="email"
           class="form-control @(Errors.ContainsKey("Email") ? "is-invalid" : "")"
           @bind="Model.Email" @bind:event="oninput" />
    @if (Errors.TryGetValue("Email", out var emailErr))
    {
        <div class="invalid-feedback">@emailErr</div>
    }
</div>

<div class="mb-3">
    <label for="phone" class="form-label">Phone <span class="text-danger">*</span></label>
    <input id="phone" type="tel" class="form-control @(Errors.ContainsKey("Phone") ? "is-invalid" : "")"
           @bind="Model.Phone" @bind:event="oninput" />
    @if (Errors.TryGetValue("Phone", out var phoneErr))
    {
        <div class="invalid-feedback">@phoneErr</div>
    }
</div>

<div class="mb-3">
    <label for="address" class="form-label">Address <span class="text-danger">*</span></label>
    <textarea id="address" class="form-control @(Errors.ContainsKey("Address") ? "is-invalid" : "")"
              rows="2" @bind="Model.Address" @bind:event="oninput"></textarea>
    @if (Errors.TryGetValue("Address", out var addrErr))
    {
        <div class="invalid-feedback">@addrErr</div>
    }
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="OnNextClick" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next &raquo;</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter] public Dictionary<string, string> Errors { get; set; } = new();
    [Parameter] public bool IsValidating { get; set; }

    private async Task OnNextClick() => await OnNext.InvokeAsync();

    public class PersonalInfoModel
    {
        public string FullName { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
        public string Address { get; set; } = "";
    }
}

