@namespace sv_6c71dd576b2f43599dfc557f722459da.Components.Pages.ApplySteps

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                    <input class="form-control @ValidationClass(index, "Company")" @bind="entry.Company" @bind:event="oninput" />
                    @if (GetError(index, "Company") is { } compErr)
                    {
                        <div class="invalid-feedback">@compErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input class="form-control @ValidationClass(index, "Title")" @bind="entry.Title" @bind:event="oninput" />
                    @if (GetError(index, "Title") is { } titleErr)
                    {
                        <div class="invalid-feedback">@titleErr</div>
                    }
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control @ValidationClass(index, "StartDate")" @bind="entry.StartDate" />
                    @if (GetError(index, "StartDate") is { } sdErr)
                    {
                        <div class="invalid-feedback">@sdErr</div>
                    }
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input type="checkbox" class="form-check-input" id="current-@index"
                               @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description <span class="text-danger">*</span></label>
                    <textarea class="form-control @ValidationClass(index, "Description")" rows="3"
                              @bind="entry.Description" @bind:event="oninput"></textarea>
                    @if (GetError(index, "Description") is { } descErr)
                    {
                        <div class="invalid-feedback">@descErr</div>
                    }
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter] public Dictionary<string, string> Errors { get; set; } = new();

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index) => Entries.RemoveAt(index);

    private string? GetError(int index, string field)
    {
        var key = $"Work[{index}].{field}";
        return Errors.TryGetValue(key, out var err) ? err : null;
    }

    private string ValidationClass(int index, string field) =>
        GetError(index, field) is not null ? "is-invalid" : "";

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

