@namespace sv_6c71dd576b2f43599dfc557f722459da.Components.Pages.ApplySteps

<h4 class="mb-3">References</h4>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    var r = References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (References.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input class="form-control @ValidationClass(index, "Name")" @bind="r.Name" @bind:event="oninput" />
                    @if (GetError(index, "Name") is { } nameErr)
                    {
                        <div class="invalid-feedback">@nameErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input class="form-control @ValidationClass(index, "Relationship")" @bind="r.Relationship" @bind:event="oninput" />
                    @if (GetError(index, "Relationship") is { } relErr)
                    {
                        <div class="invalid-feedback">@relErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control @ValidationClass(index, "Email")" @bind="r.Email" @bind:event="oninput" />
                    @if (GetError(index, "Email") is { } emailErr)
                    {
                        <div class="invalid-feedback">@emailErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control @ValidationClass(index, "Phone")" @bind="r.Phone" @bind:event="oninput" />
                    @if (GetError(index, "Phone") is { } phoneErr)
                    {
                        <div class="invalid-feedback">@phoneErr</div>
                    }
                </div>
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-primary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter] public Dictionary<string, string> Errors { get; set; } = new();

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index) => References.RemoveAt(index);

    private string? GetError(int index, string field)
    {
        var key = $"Ref[{index}].{field}";
        return Errors.TryGetValue(key, out var err) ? err : null;
    }

    private string ValidationClass(int index, string field) =>
        GetError(index, field) is not null ? "is-invalid" : "";

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

